const wh = $('Webhook: Send Payment Now').first().json;
const body = wh.body || wh;
const secret = String($env.N8N_WEBHOOK_SECRET || '').trim();
if (secret) {
  const got = String(wh.headers?.['x-n8n-secret'] || wh.headers?.['X-N8n-Secret'] || '').trim();
  if (got !== secret) {
    return [{ json: { ok: false, should_send: false, precheck_error: 'unauthorized', form_timestamp: '' } }];
  }
}

const targetTs = String(body.form_timestamp || '').trim();
if (!targetTs) {
  return [{ json: { ok: false, should_send: false, precheck_error: 'missing_form_timestamp', form_timestamp: '' } }];
}

const payResp = $('HTTP: Read Payments (DB)').first().json || {};
const prodResp = $('HTTP: Read Products (DB)').first().json || {};
const pausedResp = $('HTTP: Read Paused Chats (Payment DB)').first().json || {};

const allRows = Array.isArray(payResp.rows) ? payResp.rows : [];
const r = allRows.find((row) => String(row.timestamp || row.id || '').trim() === targetTs);
if (!r) {
  return [{ json: { ok: false, should_send: false, precheck_error: 'payment_not_found', form_timestamp: targetTs } }];
}

const FIXED_CONFIRMATION = 'تم تأكيد الدفع.';
const pdfByCode = {};
for (const p of prodResp.products || []) {
  const c = String(p.product_code || '').trim().toLowerCase();
  const u = String(p.pdf_url || '').trim();
  if (c && u) pdfByCode[c] = u;
}

function normalizePhone(v) {
  let d = String(v ?? '').replace(/\D/g, '');
  if (!d) return '';
  if (d.startsWith('20') && d.length === 12) return d;
  if (d.startsWith('0') && d.length === 11) return '20' + d.slice(1);
  if (!d.startsWith('20') && d.length === 10) return '20' + d;
  return d;
}

function isPhonePaused(phone) {
  const rows = Array.isArray(pausedResp.rows) ? pausedResp.rows : [];
  const p = normalizePhone(phone);
  const now = Date.now();
  for (const row of rows) {
    if (normalizePhone(row.phone) !== p) continue;
    if (row.active === false) continue;
    const exp = new Date(row.expires_at).getTime();
    if (Number.isFinite(exp) && exp > now) return true;
  }
  return false;
}

const done = Boolean(r.done);
const status = String(r.whatsapp_status || '').trim().toLowerCase();
const phone = normalizePhone(r.phone);
let precheckError = '';

if (!done) precheckError = 'payment_not_confirmed';
else if (status === 'sent') precheckError = 'already_sent';
else if (status === 'dead_letter') precheckError = 'dead_letter';
else if (!phone) precheckError = 'missing_phone';
else if (!/^20\d{10}$/.test(phone)) precheckError = 'invalid_phone';
else if (isPhonePaused(phone)) precheckError = 'human_handoff_paused';

const productCodeNorm = String(r.product_code || '').trim().toLowerCase();
const pdfUrl = productCodeNorm ? (pdfByCode[productCodeNorm] || '') : '';
const confirmation_text = pdfUrl
  ? FIXED_CONFIRMATION + '\n\nرابط تحميل الكتاب (PDF):\n' + pdfUrl
  : FIXED_CONFIRMATION + '\n\nلم يُعثر على رابط PDF لهذا الكتاب؛ سنتواصل معك لاحقًا.';

const processed_at = new Date().toISOString();
const should_send = precheckError === '';

return [{
  json: {
    ok: true,
    form_timestamp: targetTs,
    phone,
    confirmation_text,
    pdf_url: pdfUrl,
    product_code: r.product_code,
    should_send,
    precheck_error: precheckError,
    processed_at,
    stage: should_send ? 'ready_to_send' : 'precheck_failed'
  }
}];
